import assert from "node:assert/strict";
import { liveRows, makeRows, snapshot } from "./support/rows.mjs";

/**
 * FROZEN regression scenarios. Do not edit this file — it is the evidence the repair is graded on, and the verifier
 * checks its content digest on every run.
 *
 * Two separate features misbehave here and they misbehave for ONE reason. Every scenario takes its own baseline and
 * compares against that, so none of them depends on which scenario ran first.
 */

const optionsModule = () => import("../src/options.mjs");
const reportModule = () => import("../src/report.mjs");
const exportModule = () => import("../src/exporter.mjs");

export const scenarios = [
	{
		id: "the-shipped-defaults-survive-a-call-with-overrides",
		title: "asking for custom options does not change what the next caller starts from",
		async check() {
			const { withDefaults } = await optionsModule();
			const before = snapshot(withDefaults());
			withDefaults({ pageSize: 7, includeArchived: true, columns: ["id"] });
			const after = snapshot(withDefaults());
			assert.deepEqual(after, before, "one call's overrides became the next call's defaults");
		},
	},
	{
		id: "one-report-does-not-change-the-next-report",
		title: "a report built with overrides leaves the next default report alone",
		async check() {
			const { buildReport } = await reportModule();
			const rows = makeRows();
			const baseline = snapshot(buildReport(rows));
			buildReport(rows, { pageSize: 3, includeArchived: true });
			const again = snapshot(buildReport(rows));
			assert.equal(again.pageSize, baseline.pageSize, "the custom page size survived into the next default report");
			assert.equal(
				again.includeArchived,
				baseline.includeArchived,
				"the custom includeArchived survived into the next default report",
			);
			assert.deepEqual(
				again.rows.map((row) => row.id),
				baseline.rows.map((row) => row.id),
				"two default reports over the same rows must contain the same rows",
			);
		},
	},
	{
		id: "report-overrides-do-not-leak-into-an-export",
		title: "what a caller asked a report for has no effect on an export",
		async check() {
			const { buildReport } = await reportModule();
			const { buildExport } = await exportModule();
			const rows = makeRows();
			const baseline = snapshot(buildExport(rows));
			buildReport(rows, { pageSize: 2, includeArchived: true, columns: ["id"] });
			const after = snapshot(buildExport(rows));
			assert.equal(after.pageSize, baseline.pageSize, "the report's page size leaked into the export");
			assert.equal(after.includeArchived, baseline.includeArchived, "the report's includeArchived leaked into the export");
			assert.deepEqual(after.lines, baseline.lines, "the export changed because a report was built in between");
		},
	},
	{
		id: "report-columns-do-not-grow-across-calls",
		title: "every report carries the same columns, each of them once",
		async check() {
			const { buildReport } = await reportModule();
			const rows = makeRows();
			const first = snapshot(buildReport(rows).columns);
			const second = snapshot(buildReport(rows).columns);
			assert.deepEqual(second, first, "two reports over the same rows must carry the same columns");
			assert.equal(
				new Set(second).size,
				second.length,
				`a column may appear once in a report, but these do not: ${second.join(", ")}`,
			);
		},
	},
	{
		id: "interleaved-report-and-export-calls-stay-independent",
		title: "a run of custom calls in either feature never moves the other feature's defaults",
		async check() {
			const { buildReport } = await reportModule();
			const { buildExport } = await exportModule();
			const rows = makeRows();
			const reportBaseline = snapshot(buildReport(rows));
			const exportBaseline = snapshot(buildExport(rows));
			const sequence = [
				["report", { pageSize: 2 }],
				["export", { includeArchived: true }],
				["report", { columns: ["id"] }],
				["export", { pageSize: 1 }],
				["report", { includeArchived: true, pageSize: 4 }],
			];
			for (const [feature, overrides] of sequence) {
				if (feature === "report") buildReport(rows, overrides);
				else buildExport(rows, overrides);
				const where = `after a ${feature} call with ${JSON.stringify(overrides)}`;
				const nextReport = snapshot(buildReport(rows));
				const nextExport = snapshot(buildExport(rows));
				assert.equal(nextReport.pageSize, reportBaseline.pageSize, `${where} the default report's page size moved`);
				assert.equal(
					nextReport.includeArchived,
					reportBaseline.includeArchived,
					`${where} the default report's includeArchived moved`,
				);
				assert.deepEqual(nextExport.lines, exportBaseline.lines, `${where} the default export's contents moved`);
				assert.equal(
					nextExport.includeArchived,
					exportBaseline.includeArchived,
					`${where} the default export's includeArchived moved`,
				);
			}
		},
	},
	{
		id: "explicit-overrides-still-take-effect",
		title: "overrides a caller does pass are honoured by both features",
		async check() {
			const { buildReport } = await reportModule();
			const { buildExport } = await exportModule();
			const rows = makeRows();
			const small = buildReport(rows, { pageSize: 2, includeArchived: false });
			assert.equal(small.pageSize, 2, "an explicit page size must be used");
			assert.equal(small.rows.length, 2, "an explicit page size of 2 must return two rows");
			const everything = buildExport(rows, { includeArchived: true, pageSize: 100 });
			assert.equal(everything.lines.length, rows.length, "includeArchived: true must export the archived rows too");
			const live = buildExport(rows, { includeArchived: false, pageSize: 100 });
			assert.equal(live.lines.length, liveRows(rows).length, "includeArchived: false must leave the archived rows out");
		},
	},
];
